import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { Refresh } from '@mui/icons-material';

const Awards = () => {
  const [awardsData, setAwardsData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbyL-zZCAlZI7nzdYIQWlo8eTjhOPi46a3Or1aysJwiUZqIRMlqAtY_1Y0R1D8g8EU1i9w/exec';

  const fetchAwardsData = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Fetching awards data from:', SCRIPT_URL);
      
      // Add timestamp to avoid caching
      const response = await fetch(`${SCRIPT_URL}?timestamp=${Date.now()}`, {
        method: 'GET',
        mode: 'no-cors' // Remove this line if it causes issues, or keep it as 'cors'
      });
      
      console.log('Response status:', response.status, response.statusText);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const result = await response.json();
      console.log('Full API Response:', result);
      
      // Handle different response structures
      if (result && result.success !== undefined) {
        if (result.success && Array.isArray(result.data)) {
          console.log('Data received:', result.data);
          setAwardsData(result.data);
        } else {
          throw new Error(result.error || 'API returned unsuccessful response');
        }
      } else if (Array.isArray(result)) {
        // If the API returns just an array
        console.log('Array data received:', result);
        setAwardsData(result);
      } else {
        console.warn('Unexpected response format:', result);
        throw new Error('Unexpected response format from API');
      }
      
    } catch (err) {
      console.error('Fetch error details:', err);
      setError(`Error loading certificates: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  useEffect(() => {
    fetchAwardsData();
  }, []);

  const testAPIDirectly = () => {
    window.open(SCRIPT_URL, '_blank');
  };

  const forceSync = () => {
    window.open(`${SCRIPT_URL}?action=sync`, '_blank');
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px" flexDirection="column" gap={2}>
        <CircularProgress />
        <Typography variant="body1">Loading certificates...</Typography>
        <Typography variant="body2" color="text.secondary">
          Checking BT Certs folder...
        </Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 500 }}>
          <Typography variant="h6">Error Loading Certificates</Typography>
          <Typography variant="body2">{error}</Typography>
        </Alert>
        
        <Box display="flex" gap={2} flexDirection={{ xs: 'column', sm: 'row' }}>
          <Button variant="contained" startIcon={<Refresh />} onClick={fetchAwardsData}>
            Try Again
          </Button>
          <Button variant="outlined" onClick={testAPIDirectly}>
            Test API Directly
          </Button>
          <Button variant="outlined" onClick={forceSync}>
            Force Sync
          </Button>
        </Box>
        
        <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 2 }}>
          Check the browser console for detailed error information.
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      <Typography variant="h4" component="h1" align="center" gutterBottom sx={{ fontSize: { xs: '1.75rem', sm: '2.5rem', md: '3rem' }, mb: 1 }}>
        Awards & Certificates
      </Typography>
      
      <Typography variant="h6" component="p" align="center" color="text.secondary" sx={{ mb: 3 }}>
        {awardsData.length} {awardsData.length === 1 ? 'certificate' : 'certificates'} found
      </Typography>

      {awardsData.length === 0 ? (
        <Box textAlign="center" p={3}>
          <Typography variant="body1" color="text.secondary" gutterBottom>
            No certificates found in the BT Certs folder.
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            The sheet exists but no image data was found.
          </Typography>
          <Box display="flex" gap={2} justifyContent="center" flexDirection={{ xs: 'column', sm: 'row' }}>
            <Button variant="outlined" startIcon={<Refresh />} onClick={fetchAwardsData}>
              Refresh
            </Button>
            <Button variant="outlined" onClick={forceSync}>
              Sync Folder
            </Button>
          </Box>
        </Box>
      ) : (
        <>
          <Box sx={{ 
            display: 'grid',
            gridTemplateColumns: `repeat(${getColumns()}, 1fr)`,
            gap: 2,
            '@media (max-width: 600px)': {
              gridTemplateColumns: 'repeat(2, 1fr)',
              gap: 1,
            }
          }}>
            {awardsData.map((item, idx) => (
              <Box key={idx} sx={{ 
                borderRadius: 2, 
                overflow: 'hidden', 
                boxShadow: 1, 
                transition: 'all 0.3s ease', 
                backgroundColor: 'background.paper', 
                '&:hover': { 
                  transform: 'translateY(-4px)', 
                  boxShadow: 4 
                }
              }}>
                <Box 
                  component="img" 
                  src={item.imageUrl} 
                  alt={item.fileName} 
                  loading="lazy" 
                  sx={{ 
                    width: '100%', 
                    height: 'auto', 
                    display: 'block',
                    minHeight: 200,
                    objectFit: 'cover'
                  }} 
                  onError={(e) => {
                    console.error('Error loading image:', item.imageUrl);
                    e.target.style.display = 'none';
                  }}
                />
                
                <Box sx={{ p: 1 }}>
                  <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                    {item.fileName}
                  </Typography>
                  {item.description && (
                    <Typography variant="body2" color="text.secondary">
                      {item.description}
                    </Typography>
                  )}
                </Box>
              </Box>
            ))}
          </Box>
          
          <Box textAlign="center" mt={3}>
            <Button variant="outlined" startIcon={<Refresh />} onClick={fetchAwardsData}>
              Refresh Certificates
            </Button>
          </Box>
        </>
      )}
    </Box>
  );
};

export default Awards;
